sp_widget.client_script:
api.controller=function() {

  var c = this;

  c.scanID = function() {

    alert("Scanning Student ID...\n\nPlease wait...");

    c.data.action = "verify";
    c.server.update();

  };

};

sp_widget.script:
(function() {

    data.studentName = '';
    data.verificationStatus = '';

    var gr = new GlideRecord('x_snc_campus_con_0_student_profile');
    gr.addQuery('student', gs.getUserID());
    gr.query();

    if (gr.next()) {

        // When Scan ID button is clicked
        if (input && input.action == 'verify') {
            gr.setValue('verification_status', 'Verified');
            gr.update();
        }

        data.studentName = gr.getDisplayValue('student');
        data.verificationStatus = gr.getDisplayValue('verification_status');
    }

})();
